:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f5;
  --accent: #ffb86c;
  --accent-hover: #ffc98a;
  --accent-active: #e6a45a;
  --hunger: #ff6b6b;
  --happiness: #feca57;
  --energy: #48dbfb;
  --focus: #ffffff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--accent);
}

.pet-stage {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 160px;
  height: 160px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 50%;
}

.pet {
  width: 100px;
  height: 100px;
  background: var(--accent);
  border-radius: 20% 20% 30% 30%;
  position: relative;
  transition: transform 0.2s ease, background 0.3s ease;
  image-rendering: pixelated;
  box-shadow: inset -6px -6px 0 rgba(0, 0, 0, 0.15);
}

.pet::before,
.pet::after {
  content: '';
  position: absolute;
  top: -18px;
  width: 24px;
  height: 24px;
  background: var(--accent);
  border-radius: 50% 50% 0 0;
}

.pet::before { left: 8px; transform: rotate(-20deg); }
.pet::after { right: 8px; transform: rotate(20deg); }

.pet-face {
  position: absolute;
  inset: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding-top: 16px;
}

.eye {
  width: 14px;
  height: 14px;
  background: var(--bg);
  border-radius: 50%;
  transition: height 0.2s ease;
}

.mouth {
  width: 24px;
  height: 12px;
  border-bottom: 4px solid var(--bg);
  border-radius: 0 0 50% 50%;
  transition: all 0.2s ease;
}

.pet.sad .mouth {
  border-bottom: none;
  border-top: 4px solid var(--bg);
  border-radius: 50% 50% 0 0;
}

.pet.sleeping .eye {
  height: 4px;
  border-radius: 2px;
  margin-top: 5px;
}

.pet.sleeping {
  background: #8a7a6a;
}

.pet.bounce {
  animation: bounce 0.3s ease;
}

@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

.mood {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--accent);
  min-height: 1.5em;
  text-align: center;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  opacity: 0.9;
}

.bar {
  width: 100%;
  height: 16px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  overflow: hidden;
}

.fill {
  height: 100%;
  width: 0%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.fill.hunger { background: var(--hunger); }
.fill.happiness { background: var(--happiness); }
.fill.energy { background: var(--energy); }

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  width: 100%;
}

button {
  flex: 1 1 0;
  min-width: 90px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--bg);
  background: var(--accent);
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  background: var(--accent-active);
  transform: scale(0.97);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; gap: 20px; }
  h1 { font-size: 1.5rem; }
  .pet-stage { width: 140px; height: 140px; }
  .pet { width: 80px; height: 80px; }
  button { min-width: 80px; padding: 10px 12px; font-size: 0.95rem; }
}

(function () {
  'use strict';

  const state = {
    hunger: 70,
    happiness: 80,
    energy: 60
  };

  const petEl = document.getElementById('pet');
  const moodEl = document.getElementById('mood');
  const bars = {
    hunger: document.getElementById('hunger-bar'),
    happiness: document.getElementById('happiness-bar'),
    energy: document.getElementById('energy-bar')
  };
  const fills = {
    hunger: document.getElementById('hunger-fill'),
    happiness: document.getElementById('happiness-fill'),
    energy: document.getElementById('energy-fill')
  };

  function clamp(value) {
    return Math.max(0, Math.min(100, Math.round(value)));
  }

  function render() {
    for (const key of Object.keys(state)) {
      const value = clamp(state[key]);
      state[key] = value;
      fills[key].style.width = value + '%';
      bars[key].setAttribute('aria-valuenow', String(value));
    }

    const avg = (state.hunger + state.happiness + state.energy) / 3;
    let mood = 'Happy';
    let moodClass = '';

    if (state.energy <= 15) {
      mood = 'Sleepy';
      moodClass = 'sleeping';
    } else if (state.hunger <= 15) {
      mood = 'Starving';
      moodClass = 'sad';
    } else if (state.happiness <= 15) {
      mood = 'Sad';
      moodClass = 'sad';
    } else if (avg >= 80) {
      mood = 'Ecstatic';
    } else if (avg >= 60) {
      mood = 'Happy';
    } else if (avg >= 40) {
      mood = 'Okay';
    } else {
      mood = 'Grumpy';
      moodClass = 'sad';
    }

    moodEl.textContent = mood;
    petEl.className = 'pet' + (moodClass ? ' ' + moodClass : '');
  }

  function bounce() {
    petEl.classList.remove('bounce');
    void petEl.offsetWidth;
    petEl.classList.add('bounce');
  }

  function feed() {
    state.hunger += 20;
    state.energy += 5;
    state.happiness += 5;
    render();
    bounce();
  }

  function play() {
    state.happiness += 20;
    state.energy -= 15;
    state.hunger -= 10;
    render();
    bounce();
  }

  function sleep() {
    state.energy += 30;
    state.hunger -= 10;
    state.happiness -= 5;
    render();
    bounce();
  }

  document.getElementById('feed-btn').addEventListener('click', feed);
  document.getElementById('play-btn').addEventListener('click', play);
  document.getElementById('sleep-btn').addEventListener('click', sleep);

  render();
})();
